import json,glob,os,re
from pathlib import Path
rev=Path(r'D:\repository\数据湖\data\cnequity\meta\revisions')
# 现有版本目录
existing_dirs=set()
for dsdir in (rev/'data').iterdir():
    if dsdir.is_dir():
        for v in dsdir.iterdir():
            if v.is_dir(): existing_dirs.add((dsdir.name, v.name))
# 各 json 记录的 revision_id / dataset
orphan=[]; alive=[]
for jf in rev.rglob('*.json'):
    try:
        d=json.load(open(jf,encoding='utf-8'))
        if not isinstance(d,dict): continue
        ds=d.get('dataset'); rid=d.get('revision_id')
        if ds and rid:
            key=(ds,rid)
            if key in existing_dirs: alive.append((jf,ds,rid))
            else: orphan.append((jf,ds,rid))
    except: pass
osz=sum(f.stat().st_size for f,_,_ in orphan)
asz=sum(f.stat().st_size for f,_,_ in alive)
print(f'孤儿收据(版本目录已删): {len(orphan)} 个, {osz/1e6:.0f} MB')
print(f'存活收据(版本存在): {len(alive)} 个, {asz/1e6:.0f} MB')
print('孤儿样本:')
for f,ds,rid in orphan[:8]: print(f'  {f.stat().st_size/1e6:6.1f}MB {ds} {rid[:10]}')
"@ 2>&1

