import sys,json; sys.path.insert(0,r'D:\repository\数据湖')
from pathlib import Path
from cnequity.storage.lifecycle import LifecycleStore
ROOT=Path(r'D:\repository\数据湖'); store=LifecycleStore(ROOT/'data/cnequity/meta')
# inspect 的 pointer_path/generation_path 是否指向这些 json
objs=store.inspect(keep=1)['objects']
# 收集 inspect 结果里引用的 path
refs=set()
for o in objs:
    for k in ('path','pointer_path','generation_path'):
        v=o.get(k)
        if v: refs.add(str(v))
# 存活对象个数
print('inspect 对象数:',len(objs))
# 孤儿 json 是否被任何对象的 pointer/generation 指向? 
import glob
rev=ROOT/'data/cnequity/meta/revisions'
existing_dirs=set()
for dsdir in (rev/'data').iterdir():
    if dsdir.is_dir():
        for v in dsdir.iterdir():
            if v.is_dir(): existing_dirs.add((dsdir.name,v.name))
orphan_json=[]
for jf in rev.rglob('*.json'):
    try:
        d=json.load(open(jf,encoding='utf-8'))
        if isinstance(d,dict) and d.get('dataset') and d.get('revision_id'):
            if (d['dataset'],d['revision_id']) not in existing_dirs: orphan_json.append(jf)
    except: pass
print('孤儿json数:',len(orphan_json))
# 有没有被 inspect 对象引用的(按文件名出现在 path)
oid_paths=' '.join(refs)
used=[j for j in orphan_json if j.name in oid_paths or any(str(j).endswith(p) or p.endswith(j.name) for p in refs)]
print('孤儿json中被inspect引用的:',len(used))
